import Control from "sap/ui/core/Control";
import ItemNavigation from "sap/ui/core/delegate/ItemNavigation";

export default class MyList extends Control {
  private itemNavigation?: ItemNavigation;

  public onsapenter(): void { this.fireEvent("press"); }
  public onsapescape(): void { this.close(); }

  public onAfterRendering(): void {
    if (!this.itemNavigation) {
      this.itemNavigation = new ItemNavigation();
      this.addDelegate(this.itemNavigation);   // arrows, Home/End, tabindex
    }
    this.itemNavigation.setRootDomRef(this.getDomRef());
    this.itemNavigation.setItemDomRefs(this.getItemDomRefs());
    this.itemNavigation.setCycling(false);
  }

  public exit(): void {
    this.itemNavigation?.destroy();
  }
}
